from pathlib import Path
import json, pandas as pd, numpy as np, importlib.util
P=Path(__file__).resolve().parent; R=P/'results'
spec=importlib.util.spec_from_file_location('core',P/'analyze_ctc_ce_lineage.py'); core=importlib.util.module_from_spec(spec); spec.loader.exec_module(core)
def cat(prefix): return pd.concat([pd.read_csv(f) for f in sorted(R.glob(prefix+'_[0-9][0-9][0-9]_[0-9][0-9][0-9].csv'))],ignore_index=True)
obs=cat('observed'); strict=cat('strict'); noemb=cat('noemb'); cal=pd.concat([pd.read_csv(f) for f in sorted(R.glob('cal_[0-9][0-9][0-9]_[0-9][0-9][0-9].csv'))],ignore_index=True); perm=pd.read_csv(R/'permutation_results.csv')
obs.to_csv(R/'grouped_split_results.csv',index=False); strict.to_csv(R/'depth1_group_sensitivity.csv',index=False); noemb.to_csv(R/'no_embryo_indicator_results.csv',index=False); cal.to_csv(R/'calibration_split_results.csv',index=False)
sm=core.summarize(obs); ssm=core.summarize(strict); nsm=core.summarize(noemb); psm=core.summarize(perm)
sm.to_csv(R/'summary.csv',index=False); ssm.to_csv(R/'depth1_group_summary.csv',index=False); nsm.to_csv(R/'no_embryo_indicator_summary.csv',index=False); psm.to_csv(R/'permutation_summary.csv',index=False)
cut=cal[cal.outcome=='complete'].groupby('estimator').delta_r2.quantile(.95).rename('complete_p95'); inc=cal[cal.outcome=='incomplete'].join(cut,on='estimator'); power=inc.assign(hit=inc.delta_r2>inc.complete_p95).groupby('estimator').hit.mean().rename('incomplete_power'); cals=pd.concat([cut,power],axis=1).reset_index(); cals['n_sim']=200; cals['history_effect_target_sd']=0.30; cals.to_csv(R/'calibration_summary.csv',index=False)
d=sm.merge(cals,on='estimator'); d['criterion_median_gt_002']=d.median_delta_r2>.02; d['criterion_positive_ge_080']=d.positive_fraction>=.80; d['criterion_above_complete_p95']=d.median_delta_r2>d.complete_p95; d['criterion_power_ge_080']=d.incomplete_power>=.80; d['all_estimator_conditions']=d[['criterion_median_gt_002','criterion_positive_ge_080','criterion_above_complete_p95','criterion_power_ge_080']].all(axis=1); stable=int(d.all_estimator_conditions.sum())>=2; d.to_csv(R/'decision_table.csv',index=False)
df=core.load_rows(); meta={'n_rows':int(len(df)),'embryos':{k:int(v) for k,v in df.embryo.value_counts().to_dict().items()},'groups_depth2':int(df.group_depth2.nunique()),'groups_depth1':int(df.group_depth1.nunique()),'observed_splits':int(obs.split.nunique()),'strict_splits':int(strict.split.nunique()),'noemb_splits':int(noemb.split.nunique()),'calibration_sims':int(cal.sim.nunique()),'max_group_overlap_primary':int(obs.group_overlap.max()),'stable_residual_history_rule_met':bool(stable),'estimators_meeting_all_conditions':d.loc[d.all_estimator_conditions,'estimator'].tolist()}; (R/'run_metadata.json').write_text(json.dumps(meta,indent=2),encoding='utf-8')
print('PRIMARY\n',sm.to_string(index=False)); print('\nCAL\n',cals.to_string(index=False)); print('\nDECISION\n',d.to_string(index=False)); print('\nSTRICT\n',ssm.to_string(index=False)); print('\nNOEMB\n',nsm.to_string(index=False)); print('\nPERM\n',psm.to_string(index=False)); print('\nMETA\n',json.dumps(meta,indent=2))
